namespace {QString u(const char*s){return QString::fromUtf8(s);}QDoubleSpinBox*num(const char*id,double lo,double hi,double v){auto*f=new QDoubleSpinBox;f->setObjectName(id);f->setRange(lo,hi);f->setDecimals(6);f->setSingleStep(.01);f->setButtonSymbols(QAbstractSpinBox::NoButtons);f->setKeyboardTracking(false);f->setValue(v);return f;}
QString cacheName(const QString&uuid,const QString&path){auto f=QFileInfo(path);auto key=uuid+"|"+f.canonicalFilePath()+"|"+QString::number(f.size())+"|"+QString::number(f.lastModified().toMSecsSinceEpoch())+"|audio0|"+QString::number(audio::algorithmVersion);char*root=obs_module_config_path("cache/");QString folder=QString::fromUtf8(root?root:"");bfree(root);QDir().mkpath(folder);return QDir(folder).filePath(QCryptographicHash::hash(key.toUtf8(),QCryptographicHash::Sha256).toHex()+".json");}
// UUID + local path, size, mtime and playback mapping are checked at every transaction boundary.
QString sourceStamp(const QString&uuid){auto*s=obs_get_source_by_uuid(uuid.toUtf8().constData());if(!s)return {};auto*d=obs_source_get_settings(s);auto file=QString::fromUtf8(obs_data_get_string(d,"local_file"));QString stamp=uuid+"|"+QString::fromUtf8(obs_source_get_unversioned_id(s))+"|"+QString::number(obs_data_get_bool(d,"is_local_file"))+"|"+file+"|"+QString::number(obs_data_get_int(d,"speed_percent"));if(!file.isEmpty())stamp+="|"+cacheName(uuid,file);obs_data_release(d);obs_source_release(s);return stamp;}
bool canLink(obs_source_t*s){if(!s)return false;auto*d=obs_source_get_settings(s);auto speed=obs_data_get_int(d,"speed_percent");bool ok=std::string(obs_source_get_unversioned_id(s))=="ffmpeg_source"&&obs_data_get_bool(d,"is_local_file")&&(speed==0||speed==100);obs_data_release(d);return ok;}
class AudioWaveform final:public QWidget{public:std::function<std::shared_ptr<audio::Analysis>()>read;explicit AudioWaveform(QWidget*p=nullptr):QWidget(p){setMinimumHeight(85);setObjectName("spatial.waveform32");}void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#17212d"));p.setPen(QColor("#adc4db"));auto a=read?read():nullptr;if(!a||a->envelope.empty()){p.drawText(rect(),Qt::AlignCenter,u("—"));return;}double peak=*std::max_element(a->envelope.begin(),a->envelope.end());p.setPen(QColor("#51cdbd"));for(int x=0;x<width();++x){size_t first=size_t(double(x)*a->envelope.size()/width()),last=std::max(first+1,size_t(double(x+1)*a->envelope.size()/width()));double v=0;for(size_t i=first;i<std::min(last,a->envelope.size());++i)v=std::max(v,a->envelope[i]);double h=std::sqrt(v/std::max(peak,1e-12))*(height()-24)*.5;p.drawLine(QPointF(x,height()*.5-h),QPointF(x,height()*.5+h));}p.setPen(QColor(242,202,110,130));for(double b:a->beats)if(a->duration>0)p.drawLine(QPointF(b/a->duration*width(),4),QPointF(b/a->duration*width(),height()-16));p.setPen(QColor("#b9cddd"));p.drawText(6,height()-3,QString::number(a->duration,'f',2)+u("秒 · 能量波形 / 实际拍点"));}};
QJsonObject encode(const audio::Analysis&a){QJsonArray beats,env;for(auto t:a.beats)beats.append(t);for(size_t i=0;i<a.envelope.size();i+=std::max(size_t(1),a.envelope.size()/2000))env.append(a.envelope[i]);return {{"bpm",a.bpm},{"confidence",a.confidence},{"duration",a.duration},{"beats",beats},{"waveform",env}};}
std::shared_ptr<audio::Analysis> decode(const QJsonObject&o){auto a=std::make_shared<audio::Analysis>();a->bpm=o.value("bpm").toDouble();a->confidence=o.value("confidence").toDouble();a->duration=o.value("duration").toDouble();for(auto v:o.value("beats").toArray())a->beats.push_back(v.toDouble());for(auto v:o.value("waveform").toArray())a->envelope.push_back(v.toDouble());return a;}}
