 bpm=num("spatial.bpm32",1,1000,120);f->addRow(u("BPM"),bpm);auto*br=new QHBoxLayout;for(double factor:{.5,2.0}){auto*b=new QPushButton(factor==.5?u("BPM ×½"):u("BPM ×2"));br->addWidget(b);connect(b,&QPushButton::clicked,this,[this,factor]{bpm->setValue(bpm->value()*factor);analysis.reset();});}auto*tap=new QPushButton(u("点按测速"));br->addWidget(tap);connect(tap,&QPushButton::clicked,this,[this]{if(!tapTimer.isValid()||tapTimer.elapsed()>3000){taps.clear();tapTimer.restart();}taps.push_back(QDateTime::currentMSecsSinceEpoch());tapTimer.restart();if(taps.size()>8)taps.erase(taps.begin());if(taps.size()>1){bpm->setValue(60000.0*(taps.size()-1)/double(taps.back()-taps.front()));analysis.reset();}});f->addRow(br);
 beatRatio=new QComboBox;beatRatio->setObjectName("spatial.beat-ratio32");for(auto pair:{std::pair<const char*,double>{"1/4 拍",.25},{"1/2 拍",.5},{"1 拍",1},{"2 拍",2},{"4 拍",4},{"自定义",0}})beatRatio->addItem(u(pair.first),pair.second);beatRatio->setCurrentIndex(2);f->addRow(u("关键帧最小拍长比例"),beatRatio);customRatio=num("spatial.custom-ratio32",.000001,10000,1);f->addRow(u("自定义拍长比例"),customRatio);minimum=num("spatial.beat-minimum32",0,100000,0);offset=num("spatial.beat-offset32",-100000,100000,0);audioStart=num("spatial.beat-start32",0,9e12,0);audioEnd=num("spatial.beat-end32",0,9e12,30);f->addRow(u("附加最小间隔 / 秒"),minimum);f->addRow(u("首拍 / 时间轴偏移 / 秒"),offset);f->addRow(u("素材范围起点 / 秒"),audioStart);f->addRow(u("素材范围终点 / 秒"),audioEnd);
 auto*buttons=new QHBoxLayout;auto*preview=new QPushButton(u("预览候选点")),*bake=new QPushButton(u("写入选中参数轨道"));preview->setObjectName("spatial.beat-preview32");bake->setObjectName("spatial.beat-bake32");buttons->addWidget(preview);buttons->addWidget(bake);f->addRow(buttons);connect(preview,&QPushButton::clicked,this,[this]{previewBeats();});connect(bake,&QPushButton::clicked,this,[this]{bakeBeats();});auto*undoBatch=new QPushButton(u("撤销上次编辑 / 生成批次"));f->addRow(undoBatch);connect(undoBatch,&QPushButton::clicked,this,[this]{undo();});
