void CameraEditor::refreshMedia(){if(!mediaChoice)return;const auto old=model->mediaLinked?QString::fromStdString(model->mediaUuid):mediaChoice->currentData().toString();QStringList names,ids;auto*sceneSource=obs_frontend_get_current_scene();auto*scene=sceneSource?obs_scene_from_source(sceneSource):nullptr;struct C{QStringList*names,*ids;}c{&names,&ids};if(scene)obs_scene_enum_items(scene,[](obs_scene_t*,obs_sceneitem_t*i,void*p){auto&c=*static_cast<C*>(p);auto*s=obs_sceneitem_get_source(i);if(!(obs_source_get_output_flags(s)&OBS_SOURCE_AUDIO))return true;QString id=QString::fromUtf8(obs_source_get_uuid(s));if(c.ids->contains(id))return true;auto*d=obs_source_get_settings(s);bool local=obs_data_get_bool(d,"is_local_file")&&QString::fromUtf8(obs_data_get_string(d,"local_file")).size()>0;QString name=QString::fromUtf8(obs_source_get_name(s))+u(local?" · 本地离线":" · 实时 / 手工BPM");c.names->push_back(name);c.ids->push_back(id);obs_data_release(d);return true;},&c);obs_source_release(sceneSource);bool same=ids.size()==mediaChoice->count();for(int i=0;same&&i<ids.size();++i)same=ids[i]==mediaChoice->itemData(i).toString()&&names[i]==mediaChoice->itemText(i);if(same){int wanted=mediaChoice->findData(old);if(wanted>=0){QSignalBlocker b(mediaChoice);mediaChoice->setCurrentIndex(wanted);}return;}QSignalBlocker b(mediaChoice);mediaChoice->clear();for(int i=0;i<ids.size();++i)mediaChoice->addItem(names[i],ids[i]);int index=mediaChoice->findData(old);if(index>=0)mediaChoice->setCurrentIndex(index);if(!old.isEmpty()&&index<0){cancelAudio=true;++audioGeneration;analysis.reset();timeline->candidates.clear();}}
void CameraEditor::analyze(){
 cancelAudio=true;cancelBake=true;++audioGeneration;analysis.reset();candidateStamp.clear();timeline->candidates.clear();if(audioThread.joinable())audioThread.join();stopCapture();const auto uuid=mediaChoice->currentData().toString();auto*s=obs_get_source_by_uuid(uuid.toUtf8().constData());auto*d=s?obs_source_get_settings(s):nullptr;QString file=d?QString::fromUtf8(obs_data_get_string(d,"local_file")):QString();bool local=d&&obs_data_get_bool(d,"is_local_file");double speed=d?obs_data_get_int(d,"speed_percent"):100;obs_data_release(d);obs_source_release(s);if(!local||file.isEmpty()){audioStatus->setText(u("此来源没有可读取本地文件。请手填 BPM 或使用显式实时采集。"));return;}if(speed!=0&&speed!=100){audioStatus->setText(u("检测到非100%播放速度；本轮离线时间映射仅支持100%，请恢复速度或使用手工BPM。"));return;}
 analyzedUuid=uuid;analyzedFile=file;const auto cache=cacheName(uuid,file);analyzedStamp=sourceStamp(uuid);QFile f(cache);if(f.open(QIODevice::ReadOnly)){analysis=decode(QJsonDocument::fromJson(f.readAll()).object());if(waveform)waveform->update();bpm->setValue(analysis->bpm>0?analysis->bpm:120);audioEnd->setValue(analysis->duration);audioStatus->setText(QString::fromUtf8("缓存：BPM %1 · 置信度 %2 · 首拍 %3s · %4 拍。候选点尚未写入。").arg(analysis->bpm).arg(analysis->confidence).arg(analysis->beats.empty()?0:analysis->beats.front()).arg(analysis->beats.size()));return;}
 cancelAudio=false;auto generation=++audioGeneration;audioStatus->setText(u("后台解码与分析中…原素材继续播放。"));audioThread=std::thread([this,file,uuid,cache,generation]{auto result=std::make_shared<audio::Analysis>(audio::analyzeFile(file.toStdWString(),cancelAudio,[this,generation,last=-1](double fraction)mutable{int percent=int(fraction*100);if(percent==last)return;last=percent;QMetaObject::invokeMethod(this,[this,generation,percent]{if(generation==audioGeneration)audioStatus->setText(QString::fromUtf8("后台音频分析 %1% · 可取消").arg(percent));},Qt::QueuedConnection);}));QMetaObject::invokeMethod(this,[this,result,uuid,cache,generation]{if(generation!=audioGeneration||uuid!=mediaChoice->currentData().toString())return;if(sourceStamp(uuid)!=analyzedStamp){audioStatus->setText(u("媒体文件或播放映射已变化，请重新分析。"));return;}if(result->cancelled){audioStatus->setText(u("已取消，未写入任何关键帧。"));return;}if(!result->error.empty()){audioStatus->setText(u("离线分析失败：")+QString::fromStdString(result->error)+u("；可手填 BPM 或实时采集。"));return;}analysis=result;if(waveform)waveform->update();bpm->setValue(result->bpm>0?result->bpm:120);audioEnd->setValue(result->duration);QSaveFile f(cache);if(f.open(QIODevice::WriteOnly)){f.write(QJsonDocument(encode(*result)).toJson(QJsonDocument::Compact));f.commit();}audioStatus->setText(QString::fromUtf8("BPM %1 · 置信度 %2 · 首拍 %3 秒 · %4 个实际拍点。%5").arg(result->bpm,0,'f',2).arg(result->confidence,0,'f',2).arg(result->beats.empty()?0:result->beats.front(),0,'f',3).arg(result->beats.size()).arg(result->confidence<.35?u("置信度低；请校正BPM，使用人工网格。"):u("可预览候选点；细分点是插值网格。")));},Qt::QueuedConnection);});
}
void CameraEditor::previewBeats(){if(analysis&&!analyzedFile.isEmpty()&&sourceStamp(analyzedUuid)!=analyzedStamp){analysis.reset();audioStatus->setText(u("音频文件已变化，请重新分析。"));return;}double ratio=beatRatio->currentData().toDouble();if(ratio<=0)ratio=customRatio->value();double start=audioStart->value(),end=audioEnd->value();if(end<=start){audioStatus->setText(u("范围终点必须大于起点。"));return;}std::vector<double> beats;bool detected=analysis&&analysis->confidence>=.35&&std::abs(bpm->value()-analysis->bpm)<.011;if(detected){for(double t:analysis->beats)if(t>=start&&t<=end)beats.push_back(t);}else{double step=60/bpm->value();double estimate=(end-start)/step;if(estimate>1000000){audioStatus->setText(u("预计超过100万参考拍，请缩小范围。"));return;}for(double t=start;t<=end;t+=step)beats.push_back(t);}
 double estimate=beats.size()/ratio;if(estimate>1000000){audioStatus->setText(u("预计超过100万候选点；请增大拍长比例或缩小范围。"));return;}auto points=audio::candidates(beats,ratio,minimum->value(),offset->value());candidateStamp=sourceStamp(mediaChoice->currentData().toString());timeline->candidates.clear();for(double t:points)if(t>=0)timeline->candidates.push_back(toTime(t));timeline->update();audioStatus->setText(QString::fromUtf8("%1 个候选点 · %2 · 最小拍长比例 %3。仅参考标记，不延长动画。").arg(points.size()).arg(detected?u("检测拍点及局部插值细分"):u("人工BPM网格")).arg(ratio));}
void CameraEditor::bakeBeats(){if(candidateStamp!=sourceStamp(mediaChoice->currentData().toString())){timeline->candidates.clear();audioStatus->setText(u("媒体或播放映射已变化，请重新分析并预览候选点。"));return;}if(activeParameter.empty()||!validParameter(active,activeParameter)){audioStatus->setText(u("先在时间轴单击具体参数轨道。"));return;}if(objectLocked(*model,active)||objectAnimation(*model,active)[activeParameter].locked){audioStatus->setText(u("轨道已锁定，未写入。"));return;}if(timeline->candidates.empty()){audioStatus->setText(u("请先预览候选点。"));return;}const int object=active;const auto param=activeParameter;const auto targetIdentity=objectId(object);const auto mediaFingerprint=candidateStamp;const auto source=objectAnimation(*model,object)[param];
 QMessageBox confirm(QMessageBox::Question,u("写入节拍关键帧"),QString::fromUtf8("将向“%1 / %2”写入最多 %3 帧（估计 %4 KB）。\n采样当前曲线，保护已有同时间帧；不会自动生成运动。整个批次可一次撤销。").arg(objectName(active)).arg(QString::fromStdString(activeParameter)).arg(timeline->candidates.size()).arg(timeline->candidates.size()*128/1024),QMessageBox::Ok|QMessageBox::Cancel,this);confirm.setDefaultButton(QMessageBox::Cancel);if(confirm.exec()!=QMessageBox::Ok)return;
 if(bakeThread.joinable()){cancelBake=true;bakeThread.join();}cancelBake=false;const auto generation=++bakeGeneration,revision=editRevision;if(object>=int(model->layers.size())||targetIdentity!=objectId(object)||mediaFingerprint!=sourceStamp(mediaChoice->currentData().toString()))return;Curve next=source;const double base=baseValue(*model,object,param);auto points=timeline->candidates;audioStatus->setText(u("后台生成关键帧中…可按取消；完成前原工程保持原样。"));
 bakeThread=std::thread([this,next=std::move(next),points=std::move(points),base,object,param,targetIdentity,source,mediaFingerprint,generation,revision]()mutable{bool enabled=next.enabled;next.enabled=true;size_t added=0,skipped=0;for(size_t i=0;i<points.size();++i){if(cancelBake)return;auto t=points[i];if(next.contains(t))++skipped;else{if(!enabled)next.put({t,base});else next.split(t,base);++added;}if(i%1000==0)QMetaObject::invokeMethod(this,[this,i,total=points.size(),generation]{if(generation==bakeGeneration)audioStatus->setText(QString::fromUtf8("后台生成 %1 / %2；可取消，整批可撤销。").arg(i).arg(total));},Qt::QueuedConnection);}
 QMetaObject::invokeMethod(this,[this,next=std::move(next),added,skipped,object,param,targetIdentity,source,mediaFingerprint,generation,revision]()mutable{if(generation!=bakeGeneration||cancelBake)return;if(revision!=editRevision||object>=int(model->layers.size())||objectLocked(*model,object)||objectId(object)!=targetIdentity||mediaFingerprint!=sourceStamp(mediaChoice->currentData().toString())||&objectAnimation(*model,object)[param].keys()!=&source.keys()||objectAnimation(*model,object)[param].locked||objectAnimation(*model,object)[param].enabled!=source.enabled){audioStatus->setText(u("生成期间工程已变化，已取消整个批次，请重新预览。"));return;}remember();objectAnimation(*model,object)[param]=std::move(next);model->timelinePreview=true;apply();audioStatus->setText(QString::fromUtf8("已写入 %1 帧，保留已有 %2 帧；撤销可恢复整个批次。").arg(added).arg(skipped));},Qt::QueuedConnection);});
}

void CameraEditor::syncMedia(bool playing){
 bool linked=mediaLink&&mediaLink->isChecked();auto uuid=mediaChoice->currentData().toString();auto*s=linked?obs_get_source_by_uuid(uuid.toUtf8().constData()):nullptr;
 if(linked&&!canLink(s)){linked=false;QSignalBlocker b(mediaLink);mediaLink->setChecked(false);audioStatus->setText(u("媒体联动仅支持100%速度的本地媒体源；已关闭联动。"));}
 bool dirty=model->mediaLinked!=linked||(linked&&(model->mediaUuid!=uuid.toStdString()||model->mediaOffset!=offset->value()));model->mediaLinked=linked;
 if(linked){model->mediaUuid=uuid.toStdString();model->mediaOffset=offset->value();obs_source_media_set_time(s,int64_t(std::max(0.0,model->timelinePosition-offset->value())*1000));obs_source_media_play_pause(s,!playing);}obs_source_release(s);
 if(dirty&&changed)changed();
}
void CameraEditor::audioCapture(void*data,obs_source_t*,const audio_data*audio,bool){auto*c=static_cast<LiveCapture*>(data);size_t used=c->frames.load(std::memory_order_relaxed),limit=c->pcm.size()/c->channels,n=std::min(size_t(audio->frames),limit-used);for(size_t i=0;i<n;++i)for(unsigned ch=0;ch<c->channels;++ch)c->pcm[(used+i)*c->channels+ch]=audio->data[ch]?reinterpret_cast<const float*>(audio->data[ch])[i]:0;c->frames.store(used+n,std::memory_order_release);}
void CameraEditor::stopCapture(){if(!liveCapture)return;obs_source_remove_audio_capture_callback(liveCapture->source,audioCapture,liveCapture.get());obs_source_release(liveCapture->source);liveCapture.reset();}
void CameraEditor::captureLive(){cancelAudio=true;const auto captureGeneration=++audioGeneration;analyzedFile.clear();analyzedStamp.clear();stopCapture();auto*s=obs_get_source_by_uuid(mediaChoice->currentData().toString().toUtf8().constData());if(!s)return;obs_audio_info info{};if(!obs_get_audio_info(&info)){obs_source_release(s);return;}liveCapture=std::make_unique<LiveCapture>();auto*c=liveCapture.get();c->source=s;c->rate=info.samples_per_sec;c->channels=get_audio_channels(info.speakers);if(!c->channels||c->channels>MAX_AV_PLANES){stopCapture();return;}c->pcm.resize(size_t(c->rate)*15*c->channels);obs_source_add_audio_capture_callback(s,audioCapture,c);audioStatus->setText(u("采集15秒中；仅复制到有界缓冲，不改变播放。"));const auto uuid=mediaChoice->currentData().toString();QTimer::singleShot(15000,this,[this,uuid,captureGeneration]{if(captureGeneration!=audioGeneration||!liveCapture||uuid!=mediaChoice->currentData().toString())return;auto*c=liveCapture.get();obs_source_remove_audio_capture_callback(c->source,audioCapture,c);obs_source_release(c->source);auto pcm=std::move(c->pcm);pcm.resize(c->frames.load(std::memory_order_acquire)*c->channels);unsigned rate=c->rate,channels=c->channels;liveCapture.reset();if(pcm.empty()){audioStatus->setText(u("无可分析音频：来源未播放、已失效或未输出PCM。"));return;}cancelAudio=true;if(audioThread.joinable())audioThread.join();cancelAudio=false;auto generation=++audioGeneration;audioThread=std::thread([this,pcm=std::move(pcm),rate,channels,generation]{auto result=std::make_shared<audio::Analysis>(audio::analyzePcm(pcm,rate,channels));QMetaObject::invokeMethod(this,[this,result,generation]{if(generation!=audioGeneration||cancelAudio)return;analysis=result;if(waveform)waveform->update();bpm->setValue(result->bpm>0?result->bpm:120);audioStart->setValue(0);audioEnd->setValue(result->duration);audioStatus->setText(QString::fromUtf8("实时已观察 %1 秒：BPM %2，置信度 %3；不推测未来拍点。").arg(result->duration).arg(result->bpm).arg(result->confidence));},Qt::QueuedConnection);});});}
